61	template <class T_PWM_IO>
62	struct pwmStrmIO {
63	    T_PWM_IO Va_cmd;
64	    T_PWM_IO Vb_cmd;
65	    T_PWM_IO Vc_cmd;
66	    T_PWM_IO dc_link;
67	    bool isEnd_cond;
68	};
69	
70	template <class T_FOC_COM>
71	void sampler_duty(long cnt_trip,
72	                  int ii_sample,
73	                  hls::stream<T_FOC_COM>& Va_cmd,
74	                  hls::stream<T_FOC_COM>& Vb_cmd,
75	                  hls::stream<T_FOC_COM>& Vc_cmd,
76	                  hls::stream<T_FOC_COM>& dc_link,
77	                  hls::stream<pwmStrmIO<T_FOC_COM> >& strm_pwm_bundle_out) {
78	    pwmStrmIO<T_FOC_COM> pwm_args;
79	
80	    int cnt_ii = 0;
81	    long i = 0;
82	    int local_ii_sample = ii_sample <= 0 ? 1 : ii_sample;
83	
84	LOOP_SVPWM_SAMPLER:
85	    while (i < cnt_trip) {
86	#pragma HLS pipeline II = 1
87	        if (cnt_ii == 0) {
88	            pwm_args.isEnd_cond = (i == (cnt_trip - 1));
89	            if (!Va_cmd.empty()) {
90	                pwm_args.Va_cmd = Va_cmd.read();
91	                pwm_args.Vb_cmd = Vb_cmd.read();
92	                pwm_args.Vc_cmd = Vc_cmd.read();
93	            }
94	            if (!dc_link.empty()) pwm_args.dc_link = dc_link.read();
95	
96	            if (!strm_pwm_bundle_out.full()) {
97	                strm_pwm_bundle_out.write(pwm_args);
98	                i++;
99	            }
100	        }
101	        // updating cnt_ii;
102	        // local_ii_sample = ii_sample <= 0 ? 1 : ii_sample;
103	        // if (cnt_ii == ii_sample)
104	        if (cnt_ii == local_ii_sample)
105	            cnt_ii = 0;
106	        else
107	            cnt_ii++;
108	    }
109	};
