111	//---------------------------------------------------------------------------
112	// split version for calculating duty persentage ratio
113	//---------------------------------------------------------------------------
114	template <class T>
115	T GetVoff(T V[3]) {
116	    T Vmin, Vmax, Voff;
117	    Vmin = (V[0] < V[1]) ? V[0] : V[1];
118	    Vmin = (V[2] < Vmin) ? V[2] : Vmin;
119	    Vmax = (V[0] > V[1]) ? V[0] : V[1];
120	    Vmax = (V[2] > Vmax) ? V[2] : Vmax;
121	    Voff = (Vmin + Vmax) >> 1;
122	    return Voff;
123	}
124	
125	template <class t_val, class t_ratio>
126	void GetRatio(t_val V_saddle, t_val MAXVAL, t_ratio& duty_ratio) {
127	    t_val MINVAL = -(MAXVAL);
128	    V_saddle = (V_saddle > MAXVAL) ? MAXVAL : V_saddle;
129	    V_saddle = (V_saddle < MINVAL) ? MINVAL : V_saddle;
130	    t_glb_q15q16 Vp_saddle;
131	#pragma HLS BIND_OP variable = Vp_saddle op = add impl = dsp
132	    Vp_saddle = V_saddle + MAXVAL;
133	    t_ratio ratio;
134	#pragma HLS BIND_OP variable = ratio op = mul impl = dsp
135	    ratio = ((Vp_saddle >> 1) / MAXVAL);
136	
137	    if (ratio >= 1) ratio = 0.99999;
138	    duty_ratio = ratio;
139	}
140	
141	template <class T_FOC_COM>
142	void calculate_ratios_core(
143	    // output
144	    ap_ufixed<17, 1> duty_ratio[3],
145	    // input
146	    T_FOC_COM Vcmd[3],
147	    T_FOC_COM dcLink_adc,
148	    int args_dc_link_ref,
149	    int args_dc_src_mode) {
150	    t_glb_q15q16 apx_dc_ref;
151	    apx_dc_ref(31, 0) = args_dc_link_ref;
152	
153	    // Selecting reference source from ADC and AXI sources
154	    T_FOC_COM V_ref = (args_dc_src_mode == MODE_PWM_DC_SRC::DC_SRC_ADC) ? dcLink_adc : (T_FOC_COM)apx_dc_ref;
155	
156	    // Calculating Triangular Carrier Wave
157	    T_FOC_COM Voff = GetVoff(Vcmd);
158	
159	    // Tanslating into saddle ware
160	    Vcmd[0] = Vcmd[0] - Voff;
161	    Vcmd[1] = Vcmd[1] - Voff;
162	    Vcmd[2] = Vcmd[2] - Voff;
163	
164	    GetRatio<T_FOC_COM, ap_ufixed<17, 1> >(Vcmd[0], V_ref, duty_ratio[0]);
165	    GetRatio<T_FOC_COM, ap_ufixed<17, 1> >(Vcmd[1], V_ref, duty_ratio[1]);
166	    GetRatio<T_FOC_COM, ap_ufixed<17, 1> >(Vcmd[2], V_ref, duty_ratio[2]);
167	}
168	
169	template <class T_FOC_COM, class T_RATIO_16b>
170	void calculate_ratios(hls::stream<pwmStrmIO<T_FOC_COM> >& strm_pwm_bundle_in,
171	                      hls::stream<T_RATIO_16b>& strm_duty_ratio_a,
172	                      hls::stream<T_RATIO_16b>& strm_duty_ratio_b,
173	                      hls::stream<T_RATIO_16b>& strm_duty_ratio_c,
174	                      volatile int& args_dc_link_ref,
175	                      volatile int& args_dc_src_mode,
176	                      hls::ap_none<int>& stt_cnt_iter,
177	                      hls::ap_none<int>& pwm_stt_Va_cmd,
178	                      hls::ap_none<int>& pwm_stt_Vb_cmd,
179	                      hls::ap_none<int>& pwm_stt_Vc_cmd) {
180	    int iter = 0;
181	    bool isEnd_cond = true;
182	    T_FOC_COM Vcmd[3];
183	    ap_ufixed<17, 1> duty_ratio[3];
184	    T_FOC_COM dcLink_adc;
185	
186	LOOP_SVPWM_RATIO:
187	    do {
188	#pragma HLS PIPELINE off
189	        pwmStrmIO<T_FOC_COM> io_bundle_args;
190	        strm_pwm_bundle_in.read(io_bundle_args); // block reading to avoid oversampling
191	
192	        Vcmd[0] = io_bundle_args.Va_cmd;
193	        Vcmd[1] = io_bundle_args.Vb_cmd;
194	        Vcmd[2] = io_bundle_args.Vc_cmd;
195	        isEnd_cond = io_bundle_args.isEnd_cond;
196	        dcLink_adc = io_bundle_args.dc_link;
197	
198	        t_glb_q15q16 pwm_Va_stt_temp = Vcmd[0];
199	        t_glb_q15q16 pwm_Vb_stt_temp = Vcmd[1];
200	        t_glb_q15q16 pwm_Vc_stt_temp = Vcmd[2];
201	
202	        pwm_stt_Va_cmd.write(pwm_Va_stt_temp.range(31, 0));
203	        pwm_stt_Vb_cmd.write(pwm_Vb_stt_temp.range(31, 0));
204	        pwm_stt_Vc_cmd.write(pwm_Vc_stt_temp.range(31, 0));
205	
206	        calculate_ratios_core<T_FOC_COM>(duty_ratio, Vcmd, dcLink_adc, args_dc_link_ref, args_dc_src_mode);
207	        stt_cnt_iter.write(iter++);
208	
209	        ap_ufixed<16, 0> r0 = (ap_ufixed<16, 0>)duty_ratio[0];
210	        ap_ufixed<16, 0> r1 = (ap_ufixed<16, 0>)duty_ratio[1];
211	        ap_ufixed<16, 0> r2 = (ap_ufixed<16, 0>)duty_ratio[2];
212	        T_RATIO_16b r0_out, r1_out, r2_out;
213	        r0_out.range(15, 0) = r0.range(15, 0);
214	        r1_out.range(15, 0) = r1.range(15, 0);
215	        r2_out.range(15, 0) = r2.range(15, 0);
216	
217	        if (!strm_duty_ratio_a.full()) {
218	            strm_duty_ratio_a.write(r0_out);
219	            strm_duty_ratio_b.write(r1_out);
220	            strm_duty_ratio_c.write(r2_out);
221	        }
222	
223	    } while (!isEnd_cond);
224	}
