226	//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
227	// clang-format off
228	/*
229	 * @brief This module is to generate output by channel
230	 * @tparam T_IN in<reg>: input data format
231	 * @param pwm_cycle in<reg>: Dead cycle, the value in test is pwm_args_dead_cycles cycles
232	 * @param pwm_cnt in<reg>: PWM duty cycles counter by each channel
233	 * @param dead_cycles in<reg>: Dead cycle, the value in test is pwm_args_dead_cycles cycles
234	 * @param shift in<reg>: 0 (0 degree Phase Shift for output), 1 (120 degree Phase Shift for output)
235	 * @param len in<reg>: local registers to hold the duty cycles length
236	 * @param strm_length out<strm>: duty cycles on the target switch
237	 * @param strm_h_pwm out<strm>: duty cycles on upper switch of the channel
238	 * @param strm_l_pwm out<strm>: duty cycles on lower switch of the channel
239	 * @param strm_pwm_sync out<strm>: sync signals by channel to sample the ADCs
240	 */
241	// clang-format on
242	
243	template <class T_IN>
244	void generate_output_chnl(T_IN pwm_cycle,
245	                          T_IN pwm_cnt,
246	                          T_IN dead_cycles,
247	                          T_IN shift,
248	                          T_IN& len,
249	                          // hls::stream<ap_ufixed<16,0> >& strm_length,
250	                          ap_ufixed<16, 0>& duty_cycles_in,
251	                          hls::stream<ap_uint<1> >& strm_h_pwm,
252	                          hls::stream<ap_uint<1> >& strm_l_pwm,
253	                          hls::stream<ap_uint<1> >& strm_pwm_sync) {
254	#pragma HLS INLINE
255	    T_IN max_len;
256	#pragma HLS BIND_OP variable = max_len op = add impl = dsp
257	    max_len = pwm_cycle - dead_cycles;
258	    T_IN dead2 = (dead_cycles + 1) >> 1;
259	    // updating pwm_cnt2
260	    int pwm_cnt2;
261	#pragma HLS BIND_OP variable = pwm_cnt2 op = add impl = dsp
262	    pwm_cnt2 = pwm_cnt - shift;
263	
264	    if (pwm_cnt2 < 0) pwm_cnt2 += pwm_cycle;
265	
266	    ap_ufixed<16, 0> tmp_len = 0;
267	    if (pwm_cnt2 == 0) {
268	        // strm_length.read_nb(tmp_len);
269	        tmp_len = duty_cycles_in;
270	        len = tmp_len * pwm_cycle;
271	    }
272	    if (len > max_len) len = max_len;
273	
274	    // calculating start and end
275	    T_IN start = (pwm_cycle - len) >> 1;
276	    T_IN end = start + len;
277	
278	    // calculating output
279	    ap_uint<1> h_pwm, l_pwm, pwm_sync;
280	    if (pwm_cnt2 <= start || pwm_cnt2 > end) // when start==end also be 0
281	        h_pwm = 0;
282	    else //(start, end]
283	        h_pwm = 1;
284	
285	    if (pwm_cnt2 <= start - dead2 || pwm_cnt2 > end + dead2)
286	        l_pwm = 1;
287	    else
288	        l_pwm = 0;
289	    if (pwm_cnt2 == (pwm_cycle >> 1)) // always at the central of pwm_cnt
290	        pwm_sync = 1;
291	    else
292	        pwm_sync = 0;
293	    strm_h_pwm.write_nb(h_pwm);
294	    strm_l_pwm.write_nb(l_pwm);
295	    strm_pwm_sync.write_nb(pwm_sync);
296	}
297	
298	template <class T_IN>
299	struct gen_sampler_pkg {
300	    T_IN duty_ratio_a;
301	    T_IN duty_ratio_b;
302	    T_IN duty_ratio_c;
303	    int pwm_freq;
304	    int dead_cycles;
305	    int phase_shift;
306	    long trip_cnt;
307	};
308	
309	template <class T_RATIO_16b, class T_OUT>
310	void sampler_gen(hls::stream<T_RATIO_16b>& strm_duty_ratio_a,
311	                 hls::stream<T_RATIO_16b>& strm_duty_ratio_b,
312	                 hls::stream<T_RATIO_16b>& strm_duty_ratio_c,
313	                 hls::stream<gen_sampler_pkg<T_OUT> >& strm_sampler_pkg_out,
314	                 volatile int& pwm_args_pwm_freq,
315	                 volatile int& pwm_args_dead_cycles,
316	                 volatile int& pwm_args_phase_shift,
317	                 volatile long& pwm_args_cnt_trip,
318	                 int ii_sample) {
319	    long iter = 0;
320	    int cnt_ii = 0;
321	    T_RATIO_16b local_duty_ratio_a;
322	    T_RATIO_16b local_duty_ratio_b;
323	    T_RATIO_16b local_duty_ratio_c;
324	    gen_sampler_pkg<T_OUT> local_sampler_pkg;
325	
326	LOOP_GEN_SAMPLER:
327	    do {
328	#pragma HLS pipeline II = 1
329	        // if(!strm_duty_ratio_a.empty()){
330	        if (cnt_ii == 0) {
331	            strm_duty_ratio_a.read(local_duty_ratio_a);
332	            strm_duty_ratio_b.read(local_duty_ratio_b);
333	            strm_duty_ratio_c.read(local_duty_ratio_c);
334	
335	            local_sampler_pkg.duty_ratio_a.range(15, 0) = local_duty_ratio_a.range(15, 0);
336	            local_sampler_pkg.duty_ratio_b.range(15, 0) = local_duty_ratio_b.range(15, 0);
337	            local_sampler_pkg.duty_ratio_c.range(15, 0) = local_duty_ratio_c.range(15, 0);
338	
339	            local_sampler_pkg.pwm_freq = pwm_args_pwm_freq;
340	            local_sampler_pkg.dead_cycles = pwm_args_dead_cycles;
341	            local_sampler_pkg.phase_shift = pwm_args_phase_shift;
342	            local_sampler_pkg.trip_cnt = pwm_args_cnt_trip;
343	
344	            strm_sampler_pkg_out.write(local_sampler_pkg);
345	
346	            iter++;
347	        }
348	
349	        // updating cnt_ii;
350	        if (cnt_ii == ii_sample)
351	            cnt_ii = 0;
352	        else
353	            cnt_ii++;
354	
355	    } while (iter < pwm_args_cnt_trip);
356	}
357	
358	static void PWM_gen_wave(hls::stream<gen_sampler_pkg<ap_ufixed<16, 0> > >& strm_sampler_pkg,
359	                         hls::stream<ap_uint<1> >& strm_h_a,
360	                         hls::stream<ap_uint<1> >& strm_h_b,
361	                         hls::stream<ap_uint<1> >& strm_h_c,
362	                         hls::stream<ap_uint<1> >& strm_l_a,
363	                         hls::stream<ap_uint<1> >& strm_l_b,
364	                         hls::stream<ap_uint<1> >& strm_l_c,
365	                         hls::stream<ap_uint<1> >& strm_sync_a,
366	                         hls::stream<ap_uint<1> >& strm_sync_b,
367	                         hls::stream<ap_uint<1> >& strm_sync_c,
368	                         volatile int& pwm_stt_pwm_cycle) {
369	    gen_sampler_pkg<ap_ufixed<16, 0> > local_args;
370	    strm_sampler_pkg.read(local_args);
371	
372	    int clk_freq = COMM_CLOCK_FREQ; // pwm_args[SVPWM_ARGS_IDX::CLK_FQ];
373	
374	    int pwm_freq = local_args.pwm_freq;
375	    CheckRange<int>(pwm_freq, RANGE_pwm_freq);
376	    int pwm_args_pwm_freq = pwm_freq; // write back the default value if using default value
377	    long pwm_args_cnt_trip = local_args.trip_cnt;
378	
379	    ap_uint<18> pwm_cycle;
380	#pragma HLS BIND_OP variable = pwm_cycle op = mul impl = dsp
381	    pwm_cycle = clk_freq / pwm_freq;
382	
383	    bool phase_shift_mode;
384	
385	    ap_uint<18> pwm_cnt = 0;
386	    ap_uint<1> pwm_h[3] = {0, 0, 0};
387	    ap_uint<1> pwm_l[3] = {0, 0, 0};
388	    ap_uint<1> pwm_sync_temp[3] = {0, 0, 0};
389	    long iter = 0;
390	
391	    ap_uint<18> len[3] = {0, 0, 0};
392	    ap_uint<18> start[3] = {0, 0, 0};
393	    ap_uint<18> end[3] = {0, 0, 0};
394	    ap_uint<18> pwm_cnt2[3] = {0, 0, 0};
395	    ap_uint<18> shift[3] = {0, 0, 0};
396	    ap_uint<18> dead_cycles;
397	    bool toBeEnd = false;
398	    bool alreadEnd = false;
399	
400	    dead_cycles = local_args.dead_cycles;                                           // interface
401	    phase_shift_mode = (local_args.phase_shift == MODE_PWM_PHASE_SHIFT::SHIFT_120); // interface
402	
403	    if (phase_shift_mode) {
404	        int phase2_3;
405	#pragma HLS BIND_OP variable = phase2_3 op = mul impl = dsp
406	        phase2_3 = ((pwm_cycle << 1) + 1) / 3;
407	        shift[0] = 0;
408	        shift[1] = phase2_3 >> 1;
409	        shift[2] = phase2_3;
410	    } else {
411	        shift[0] = 0;
412	        shift[1] = 0;
413	        shift[2] = 0;
414	    }
415	
416	LOOP_GEN_WAVE:
417	    do {
418	#pragma HLS pipeline II = 1
419	
420	        pwm_stt_pwm_cycle = pwm_cycle;
421	
422	        generate_output_chnl<ap_uint<18> >(pwm_cycle, pwm_cnt, dead_cycles, shift[0], len[0], local_args.duty_ratio_a,
423	                                           strm_h_a, strm_l_a, strm_sync_a);
424	        generate_output_chnl<ap_uint<18> >(pwm_cycle, pwm_cnt, dead_cycles, shift[1], len[1], local_args.duty_ratio_b,
425	                                           strm_h_b, strm_l_b, strm_sync_b);
426	        generate_output_chnl<ap_uint<18> >(pwm_cycle, pwm_cnt, dead_cycles, shift[2], len[2], local_args.duty_ratio_c,
427	                                           strm_h_c, strm_l_c, strm_sync_c);
428	
429	        if (pwm_cnt + 1 == pwm_cycle) {
430	            if (toBeEnd)
431	                alreadEnd = true;
432	            else {
433	                pwm_cnt = 0;
434	                // if(!strm_sampler_pkg.empty())
435	                {
436	                    // strm_sampler_pkg.read(local_args);
437	                    iter++;
438	                    toBeEnd = (iter == (pwm_args_cnt_trip - 1));
439	                    dead_cycles = local_args.dead_cycles;
440	                    phase_shift_mode = (local_args.phase_shift == MODE_PWM_PHASE_SHIFT::SHIFT_120);
441	                    // toBeEnd = args.isEnd_cond;
442	                    if (phase_shift_mode) {
443	                        int phase2_3;
444	#pragma HLS BIND_OP variable = phase2_3 op = mul impl = dsp
445	                        phase2_3 = ((pwm_cycle << 1) + 1) / 3;
446	                        shift[0] = 0;
447	                        shift[1] = phase2_3 >> 1;
448	                        shift[2] = phase2_3;
449	                    } else {
450	                        shift[0] = 0;
451	                        shift[1] = 0;
452	                        shift[2] = 0;
453	                    }
454	                }
455	            }
456	        } else {
457	            pwm_cnt++;
458	#ifdef __SYNTHESIS__
459	            if (!strm_sampler_pkg.empty()) // always try to consume out the intput stream and only keep the latest
460	                                           // ratios
461	                strm_sampler_pkg.read(local_args);
462	#else
463	            if ((pwm_cnt + 2 == pwm_cycle) && (!strm_sampler_pkg.empty())) strm_sampler_pkg.read(local_args);
464	#endif
465	        }
466	
467	    } while (!alreadEnd);
468	}
469	template <class T_RATIO_16b>
470	void PWM_gen_wave(
471	    // hls::stream<gen_sampler_pkg<ap_ufixed<16,0>> > &strm_sampler_pkg,
472	    hls::stream<T_RATIO_16b>& strm_duty_ratio_a,
473	    hls::stream<T_RATIO_16b>& strm_duty_ratio_b,
474	    hls::stream<T_RATIO_16b>& strm_duty_ratio_c,
475	    volatile int& pwm_args_pwm_freq,
476	    volatile int& pwm_args_dead_cycles,
477	    volatile int& pwm_args_phase_shift,
478	    volatile long& pwm_args_cnt_trip,
479	    volatile int& pwm_args_ii_sample,
480	    hls::stream<ap_uint<1> >& strm_h_a,
481	    hls::stream<ap_uint<1> >& strm_h_b,
482	    hls::stream<ap_uint<1> >& strm_h_c,
483	    hls::stream<ap_uint<1> >& strm_l_a,
484	    hls::stream<ap_uint<1> >& strm_l_b,
485	    hls::stream<ap_uint<1> >& strm_l_c,
486	    hls::stream<ap_uint<1> >& strm_sync_a,
487	    hls::stream<ap_uint<1> >& strm_sync_b,
488	    hls::stream<ap_uint<1> >& strm_sync_c,
489	    hls::ap_none<int>& pwm_stt_pwm_cycle,
490	    hls::ap_none<int>& pwm_stt_duty_ratio_a,
491	    hls::ap_none<int>& pwm_stt_duty_ratio_b,
492	    hls::ap_none<int>& pwm_stt_duty_ratio_c) {
493	    T_RATIO_16b local_duty_ratio_a_next;
494	    T_RATIO_16b local_duty_ratio_b_next;
495	    T_RATIO_16b local_duty_ratio_c_next;
496	    T_RATIO_16b local_duty_ratio_a_inuse;
497	    T_RATIO_16b local_duty_ratio_b_inuse;
498	    T_RATIO_16b local_duty_ratio_c_inuse;
499	
500	    strm_duty_ratio_a.read(local_duty_ratio_a_inuse);
501	    strm_duty_ratio_b.read(local_duty_ratio_b_inuse);
502	    strm_duty_ratio_c.read(local_duty_ratio_c_inuse);
503	
504	    t_glb_q15q16 pwm_duty_ratio_a_temp = local_duty_ratio_a_inuse;
505	    t_glb_q15q16 pwm_duty_ratio_b_temp = local_duty_ratio_b_inuse;
506	    t_glb_q15q16 pwm_duty_ratio_c_temp = local_duty_ratio_c_inuse;
507	
508	    pwm_stt_duty_ratio_a.write(pwm_duty_ratio_a_temp.range(31, 0));
509	    pwm_stt_duty_ratio_b.write(pwm_duty_ratio_b_temp.range(31, 0));
510	    pwm_stt_duty_ratio_c.write(pwm_duty_ratio_c_temp.range(31, 0));
511	
512	    int ii_sample = pwm_args_ii_sample <= 0 ? 1 : pwm_args_ii_sample;
513	    int pwm_freq_inuse = pwm_args_pwm_freq;
514	    CheckRange<int>(pwm_freq_inuse, RANGE_pwm_freq);
515	
516	    ap_uint<18> pwm_cycle;
517	#pragma HLS BIND_OP variable = pwm_cycle op = mul impl = dsp
518	    pwm_cycle = COMM_CLOCK_FREQ / pwm_freq_inuse;
519	
520	    bool phase_shift_mode_inuse;
521	    bool phase_shift_mode_next;
522	
523	    ap_uint<18> pwm_cnt = 0;
524	    ap_uint<1> pwm_h[3] = {0, 0, 0};
525	    ap_uint<1> pwm_l[3] = {0, 0, 0};
526	    ap_uint<1> pwm_sync_temp[3] = {0, 0, 0};
527	    long iter = 0;
528	
529	    ap_uint<18> len[3] = {0, 0, 0};
530	    ap_uint<18> start[3] = {0, 0, 0};
531	    ap_uint<18> end[3] = {0, 0, 0};
532	    ap_uint<18> pwm_cnt2[3] = {0, 0, 0};
533	    ap_uint<18> shift[3] = {0, 0, 0};
534	    ap_uint<18> dead_cycles_inuse;
535	    ap_uint<18> dead_cycles_next;
536	    bool toBeEnd = false;
537	    bool alreadEnd = false;
538	
539	    dead_cycles_inuse = pwm_args_dead_cycles;
540	    phase_shift_mode_inuse = (pwm_args_phase_shift == MODE_PWM_PHASE_SHIFT::SHIFT_120);
541	
542	    if (phase_shift_mode_inuse) {
543	        int phase2_3;
544	#pragma HLS BIND_OP variable = phase2_3 op = mul impl = dsp
545	        phase2_3 = ((pwm_cycle << 1) + 1) / 3;
546	        shift[0] = 0;
547	        shift[1] = phase2_3 >> 1;
548	        shift[2] = phase2_3;
549	    } else {
550	        shift[0] = 0;
551	        shift[1] = 0;
552	        shift[2] = 0;
553	    }
554	    int cnt_ii = 1; // alwasy larger than latency of LOOP_GEN_WAVE
555	LOOP_GEN_WAVE:
556	    do {
557	#pragma HLS pipeline II = 1
558	
559	        pwm_stt_pwm_cycle.write(pwm_cycle);
560	
561	        pwm_duty_ratio_a_temp = (t_glb_q15q16)local_duty_ratio_a_inuse;
562	        pwm_duty_ratio_b_temp = (t_glb_q15q16)local_duty_ratio_b_inuse;
563	        pwm_duty_ratio_c_temp = (t_glb_q15q16)local_duty_ratio_c_inuse;
564	
565	        pwm_stt_duty_ratio_a.write(pwm_duty_ratio_a_temp.range(31, 0));
566	        pwm_stt_duty_ratio_b.write(pwm_duty_ratio_b_temp.range(31, 0));
567	        pwm_stt_duty_ratio_c.write(pwm_duty_ratio_c_temp.range(31, 0));
568	
569	        generate_output_chnl<ap_uint<18> >(pwm_cycle, pwm_cnt, dead_cycles_inuse, shift[0], len[0],
570	                                           local_duty_ratio_a_inuse, strm_h_a, strm_l_a, strm_sync_a);
571	        generate_output_chnl<ap_uint<18> >(pwm_cycle, pwm_cnt, dead_cycles_inuse, shift[1], len[1],
572	                                           local_duty_ratio_b_inuse, strm_h_b, strm_l_b, strm_sync_b);
573	        generate_output_chnl<ap_uint<18> >(pwm_cycle, pwm_cnt, dead_cycles_inuse, shift[2], len[2],
574	                                           local_duty_ratio_c_inuse, strm_h_c, strm_l_c, strm_sync_c);
575	
576	        if (pwm_cnt + 1 == pwm_cycle) {
577	            if (toBeEnd)
578	                alreadEnd = true;
579	            else {
580	                pwm_cnt = 0;
581	                // if(!strm_sampler_pkg.empty())
582	                {
583	                    iter++;
584	                    toBeEnd = (iter == (pwm_args_cnt_trip - 1));
585	                    dead_cycles_inuse = dead_cycles_next;
586	                    phase_shift_mode_inuse = (phase_shift_mode_next == MODE_PWM_PHASE_SHIFT::SHIFT_120);
587	                    // toBeEnd = args.isEnd_cond;
588	                    if (phase_shift_mode_inuse) {
589	                        int phase2_3;
590	#pragma HLS BIND_OP variable = phase2_3 op = mul impl = dsp
591	                        phase2_3 = ((pwm_cycle << 1) + 1) / 3;
592	                        shift[0] = 0;
593	                        shift[1] = phase2_3 >> 1;
594	                        shift[2] = phase2_3;
595	                    } else {
596	                        shift[0] = 0;
597	                        shift[1] = 0;
598	                        shift[2] = 0;
599	                    }
600	                    local_duty_ratio_a_inuse = local_duty_ratio_a_next;
601	                    local_duty_ratio_b_inuse = local_duty_ratio_b_next;
602	                    local_duty_ratio_c_inuse = local_duty_ratio_c_next;
603	                }
604	            }
605	        } else {
606	            pwm_cnt++;
607	
608	            if (!strm_duty_ratio_a.empty() &&
609	                (cnt_ii == 1)) // always try to consume out the intput stream and only keep the latest ratios
610	            {
611	                strm_duty_ratio_a.read(local_duty_ratio_a_next);
612	                strm_duty_ratio_b.read(local_duty_ratio_b_next);
613	                strm_duty_ratio_c.read(local_duty_ratio_c_next);
614	
615	                dead_cycles_next = pwm_args_dead_cycles;
616	                phase_shift_mode_next = pwm_args_phase_shift;
617	            }
618	            if (cnt_ii == ii_sample)
619	                cnt_ii = 1;
620	            else
621	                cnt_ii++;
622	        }
623	
624	    } while (!alreadEnd);
625	}
626	
627	} /*end of namespace details*/
