674	                                                      strm_duty_ratio_c, pwm_args_dc_link_ref, pwm_args_dc_src_mode,
675	                                                      pwm_stt_cnt_iter, pwm_stt_Va_cmd, pwm_stt_Vb_cmd, pwm_stt_Vc_cmd);
676	}
