        pwm_stt_pwm_cycle, pwm_stt_duty_ratio_a, pwm_stt_duty_ratio_b, pwm_stt_duty_ratio_c);

    /*
                hls::stream<details::gen_sampler_pkg<ap_ufixed<16,0>> > sampler_PassedPkg;
