38	//--------------------------------------------------------------------------
39	// Argument
40	//--------------------------------------------------------------------------
41	
42	enum Encoding_Mode { B_Leading_A = 0, A_Leading_B };
43	enum Dirction_QEI { clockwise_n = 0, clockwise_p };
44	struct AxiParameters_QEI { //
45	    int qei_args_cpr;
46	    int qei_args_ctrl;
47	    int qei_stts_RPM_THETA_m;
48	    int qei_stts_dir;
49	    int qei_stts_err;
50	    long qei_args_cnt_trip;
51	};
52	/// Constant values
53	#define QEI_MAX_NO_EDGE_CYCLE (1 << 30)
54	static RangeDef<ap_uint<32> > RANGE_qei_freq = {COMM_CLOCK_FREQ / 10, COMM_CLOCK_FREQ * 20,
55	                                                COMM_CLOCK_FREQ}; // min max default
56	static RangeDef<ap_uint<32> > RANGE_qei_cpr = {400, 40000, 1000}; // min max default
57	
58	namespace xf {
59	namespace motorcontrol {
60	namespace details {
61	
62	/*
63	 * @brief The QEI module uses digital noise filters to reject noise on the incoming quadrature phase signals and index
64	 * pulse.
65	 * @tparam T_bin ABI's pulse is a binary data type
66	 * @param A Input signals of a quadrature encoder Channel A.
67	 * @param B Input signals of a quadrature encoder Channel B. The A and B channels are coded ninety electrical degrees
68	 * out of phase.
69	 * @param I Input signals of a quadrature encoder Channel I. This I signal, produced once per complete revolution of the
70	 * quadrature encoder, is often used to locate a specific position during a 360° revolution.
71	 * @param trip_cnt input of trip count
72	 * @param finalABI The output of ABI by filtered
73	 */
74	template <class T_bin>
75	void filterIn(hls::stream<T_bin>& A,
76	              hls::stream<T_bin>& B,
77	              hls::stream<T_bin>& I,
78	              long trip_cnt,
79	              hls::stream<ap_uint<4> >& finalABI) {
80	    const ap_uint<5> max_filtercount = 16;
81	    ap_uint<5> filter_a = 0;
82	    ap_uint<5> filter_b = 0;
83	    ap_uint<5> filter_i = 0;
84	    T_bin f_a = 0;
85	    T_bin f_b = 0;
86	    T_bin f_i = 0;
87	    T_bin a;
88	    T_bin b;
89	    T_bin i;
90	    T_bin ini_A = 0;
91	    T_bin ini_B = 0;
92	    T_bin ini_I = 0;
93	    T_bin pre_a = 0;
94	    T_bin pre_b = 0;
95	    T_bin pre_i = 0;
96	
97	LOOP_QEI_FILTER:
98	    for (long k = 0; k < trip_cnt; k++) {
99	#pragma HLS PIPELINE II = 1
100	        auto read_a = A.read_nb(a);
101	        auto read_b = B.read_nb(b);
102	        auto read_i = I.read_nb(i);
103	        bool is_end = trip_cnt == k + 1 ? true : false;
104	        if (read_a) {
105	            ini_A = a;
106	            ini_B = b;
107	            ini_I = i;
108	        }
109	        if (pre_a ^ ini_A) filter_a = 0;
110	        if (pre_b ^ ini_B) filter_b = 0;
111	        if (pre_i ^ ini_I) filter_i = 0;
112	        pre_a = ini_A;
113	        pre_b = ini_B;
114	        pre_i = ini_I;
115	        if (filter_a < max_filtercount) filter_a++;
116	        if (filter_b < max_filtercount) filter_b++;
117	        if (filter_i < max_filtercount) filter_i++;
118	        if (filter_a == max_filtercount) f_a = ini_A;
119	        if (filter_b == max_filtercount) f_b = ini_B;
120	        if (filter_i == max_filtercount) f_i = ini_I;
121	        ap_uint<4> f_ABI;
122	        f_ABI[0] = (f_a);
123	        f_ABI[1] = (f_b);
124	        f_ABI[2] = (f_i);
125	        f_ABI[3] = (is_end);
126	        finalABI.write(f_ABI);
127	    }
128	}
129	
130	/*
131	 * @brief The structure for ABI' edges information
132	 * @param edges The variable for saving ABI's status, if there is a change (0->1 or 1->0), edges value is 1, or is 0.
133	 * @param types The type for marking ABI's status including raining(0->1) or falling(1->0)
134	 * @param timeStep Record the number of cycles on qei system time
135	 */
136	struct QEI_EdgeInfo {
137	    ap_uint<3> edges; // 2:I,1:B,0:A
138	    ap_uint<3> types; // 2:I,1:B,0:A, 1: rainsing , 0: falling
139	    unsigned int timeStep;
140	    void clone(QEI_EdgeInfo src) {
141	        edges = src.edges;
142	        types = src.types;
143	        timeStep = src.timeStep;
144	    }
145	};
146	
147	/*
148	 * @brief By catching on the rising and falling edges of the pulse train,
149	 * we can mark the state and type of the pulse and filter out invalid signals.
150	 * @tparam T_bin ABI's pulse is a binary data type
151	 * @param strm_finalABI The input signals are filtered by filterIn
152	 * @param strm_cntEdge The output signals are marked and filtered by this module
153	 */
154	template <class T_bin>
155	void catchingEdge(hls::stream<ap_uint<4> >& strm_finalABI,
156	                  hls::stream<QEI_EdgeInfo>& strm_cntEdge,
157	                  hls::stream<T_bin>& strm_calc_end) {
158	    const unsigned int max_timeStep = QEI_MAX_NO_EDGE_CYCLE;
159	    unsigned int timeStep = 0; // increasing by MAX_PERIOD
160	#pragma HLS BIND_OP variable = timeStep op = add impl = dsp
161	    QEI_EdgeInfo edgeInfo;
162	    ap_uint<4> f_ABI;
163	    T_bin va, vb, vi, is_end;
164	    T_bin va_pre, vb_pre, vi_pre;
165	    f_ABI = strm_finalABI.read();
166	    va = f_ABI[0];
167	    vb = f_ABI[1];
168	    vi = f_ABI[2];
169	    is_end = f_ABI[3];
170	    timeStep++;
171	#ifndef __SYNTHESIS__
172	    unsigned int k = 0;
173	#endif
174	LOOP_QEI_CATCH:
175	    while (!is_end) {
176	#pragma HLS PIPELINE II = 1
177	        if (!strm_finalABI.empty()) {
178	            va_pre = va;
179	            vb_pre = vb;
180	            vi_pre = vi;
181	            f_ABI = strm_finalABI.read();
182	            va = f_ABI[0];
183	            vb = f_ABI[1];
184	            vi = f_ABI[2];
185	            is_end = f_ABI[3];
186	            ap_uint<3> edges;
187	            edgeInfo.edges[0] = va_pre ^ va;
188	            edgeInfo.edges[1] = vb_pre ^ vb;
189	            edgeInfo.edges[2] = vi_pre ^ vi;
190	            edgeInfo.types[0] = va; // 0->1 : raising edge
191	            edgeInfo.types[1] = vb;
192	            edgeInfo.types[2] = vi;
193	            edgeInfo.timeStep = timeStep;
194	            if (edgeInfo.edges != 0) {
195	                strm_cntEdge.write_nb(edgeInfo);
196	                strm_calc_end.write(0);
197	            }
198	        }
199	        if (timeStep < max_timeStep - 1)
200	            timeStep++;
201	        else
202	            timeStep = 0;
203	#ifndef __SYNTHESIS__
204	        k++;
205	#endif
206	    } // while(1)
207	    strm_calc_end.write(1);
208	}
209	
210	/*
211	 * @brief Judging that both channel A and channel B have edges
212	 * @param edges_cur The current signals packet including ABI's edges, types, timeStep
213	 * @return If both A and B have edges is false, or is true
214	 */
215	static bool isNormalEdges(QEI_EdgeInfo edges_cur) {
216	#pragma HLS INLINE
217	    const int i_a = 0;
218	    const int i_b = 1;
219	    if (edges_cur.edges[i_a] == 1 && edges_cur.edges[i_b] == 1)
220	        return false;
221	    else
222	        return true;
223	}
224	
225	/*
226	 * @brief Judging that both channel A and channel B have no edges
227	 * @param edges_cur The current signals packet including ABI's edges, types, timeStep
228	 * @return If A and B have no edges is true, or is false
229	 */
230	static bool isNoABEdge(QEI_EdgeInfo edges_cur) {
231	#pragma HLS INLINE
232	    const int i_a = 0;
233	    const int i_b = 1;
234	    if (edges_cur.edges[i_a] == 0 && edges_cur.edges[i_b] == 0)
235	        return true;
236	    else
237	        return false;
238	}
239	
240	/*
241	 * @brief Determine whether the pulse is a rising edge
242	 * @param idx Index of pulse type for A, B, I
243	 * @param edges_cur The current pulse packet including ABI's edges, types, timeStep
244	 * @return If the pulse is a rising edge is true, or is false
245	 */
246	static bool isRaising(int idx, QEI_EdgeInfo edges_cur) {
247	#pragma HLS INLINE
248	    if (edges_cur.edges[idx] == 1 && edges_cur.types[idx] == 1)
249	        return true;
250	    else
251	        return false;
252	}
253	
254	/*
255	 * @brief Analyze the direction of a pulse based on its state change and type, and calculate the number of cycles
256	 * between the two pulses.
257	 * @param pre The previous status of pulse
258	 * @param cur The current status of pulse
259	 * @param mode The mode represents encoding mode, B leading A is represented by 0 and A leading B is represented by 1.
260	 * @param dir The direction of current pulse, clockwise is represented by 1 and counterclockwise is represented by 0.
261	 * @param ii_cycles The number of cycles between previous pulse and current pulse
262	 */
263	static void processABedges(QEI_EdgeInfo pre, QEI_EdgeInfo cur, ap_uint<1>& mode, bool& dir, unsigned int& ii_cycles) {
264	#pragma HLS INLINE
265	    // PRE	CUR	Leader
266	    // R	    R	PRE
267	    // F	    F	PRE
268	    // R	    F	CUR
269	    // F	    R	CUR
270	    const unsigned int max_timeStep = QEI_MAX_NO_EDGE_CYCLE;
271	    const int i_a = 0;
272	    const int i_b = 1;
273	    int id_pre = pre.edges(1, 0) / 2;
274	    int id_cur = cur.edges(1, 0) / 2;
275	    if (pre.types[id_pre] == cur.types[id_cur]) {
276	        // leader is pre
277	        if (id_pre == 0) // A is leader
278	            dir = 1 ^ mode;
279	        else
280	            dir = 0 ^ mode;
281	    } else {
282	        // leader is cur
283	        if (id_cur == 0) // A is leader
284	            dir = 1 ^ mode;
285	        else
286	            dir = 0 ^ mode;
287	    }
288	    int diff;
289	#pragma HLS BIND_OP variable = diff op = add impl = dsp
290	    diff = cur.timeStep - pre.timeStep;
291	    if (diff < 0) diff += QEI_MAX_NO_EDGE_CYCLE;
292	    ii_cycles = diff;
293	}
294	
295	/*
296	 * @brief By counting the leading and trailing edges, the counter monitors the transition in its relationship
297	 to the state of the opposite channel, and can generate reliable position and speed.
298	 * @tparam T_bin ABI's pulse is a binary data type
299	 * @tparam T_err The type for qei's error status
300	 * @param strm_cntEdge The input stream with a structure including ABI' edges, types and timeStep
301	 * @param out_speed_angle The output stream with 32 bits saving speed and angle
302	 * @param out_dirstr The output stream for direction
303	 * @param out_errstr The output stream for error
304	 * @param axi_qei_cpr Read for user setting or written back by kernel
305	 * @param axi_qei_ctrl The lowest bit of this value indicates the encoding mode
306	 * @param axi_qei_rpm_theta_m Rpm and theta_m written back by kernel on axi_lite port
307	 * @param axi_qei_dir Dir written back by kernel on axi_lite port
308	 * @param axi_qei_err Err written back by kernel on axi_lite port
309	 */
310	template <class T_bin, class T_err>
311	void calcCounter(hls::stream<QEI_EdgeInfo>& strm_cntEdge,
312	                 hls::stream<T_bin>& strm_calc_end,
313	                 hls::stream<ap_uint<32> >& out_speed_angle,
314	                 hls::stream<T_bin>& out_dirstr,
315	                 hls::stream<T_err>& out_errstr,
316	                 volatile int& axi_qei_cpr,
317	                 // volatile int& axi_qei_freq,COMM_CLOCK_FREQ
318	                 volatile int& axi_qei_ctrl,
319	                 hls::ap_none<int>& axi_qei_rpm_theta_m,
320	                 hls::ap_none<int>& axi_qei_dir,
321	                 hls::ap_none<int>& axi_qei_err) {
322	    axi_qei_rpm_theta_m.write(0);
323	    axi_qei_dir.write(0);
324	    axi_qei_err.write(0);
325	
326	    const int i_a = 0;
327	    const int i_b = 1;
328	    const int i_i = 2;
329	
330	    const unsigned int timeOut_noEdge = QEI_MAX_NO_EDGE_CYCLE;
331	    unsigned int cnt_noEdge = 0;
332	    unsigned short counter = 0;
333	#pragma HLS BIND_OP variable = counter op = add impl = dsp
334	
335	    bool isPreValid = false;
336	    bool isNoEdge = true;
337	    QEI_EdgeInfo edges_cur;
338	    QEI_EdgeInfo edges_pre;
339	
340	    T_bin is_end = strm_calc_end.read();
341	    bool dir = true; // clockwise
342	    ap_uint<32> ctrl = axi_qei_ctrl;
343	    ap_uint<1> mode = (ctrl > (ap_uint<32>)0);
344	    mode = mode ^ 1; // inversing the behavior for default setting of  axi_qei_ctrl '0' means B leading A
345	//#define DBG_CHIPSCOPE
346	#ifdef DBG_CHIPSCOPE
347	    unsigned short freqA = 0;
348	    unsigned short freqB = 0;
349	    unsigned short cnt_A = 0;
350	    unsigned short cnt_B = 0;
351	    unsigned int cnt_sec = 0;
352	#endif // DBG_CHIPSCOPE
353	#ifndef __SYNTHESIS__
354	    QEI_EdgeInfo edges_pre2; // for printing
355	    unsigned int k = 0;
356	#endif
357	LOOP_QEI_COUNTEDGE:
358	    while (!is_end) {
359	#pragma HLS PIPELINE off
360	
361	        ap_uint<32> cpr = axi_qei_cpr;
362	        CheckRange(cpr, RANGE_qei_cpr);
363	        axi_qei_cpr = cpr;
364	        ap_uint<32> freq = COMM_CLOCK_FREQ;
365	
366	        unsigned int ii_cycles;
367	        unsigned short speed_rpm;
368	
369	#ifdef DBG_CHIPSCOPE
370	        const int ii_after_synthesis = 4;
371	        const int div_factor =
372	            100 *
373	            ii_after_synthesis; // for simulation, div_factor can be larger value, for running on hardware, it can be 1
374	        if (cnt_sec == freq / div_factor) { // if(cnt_sec == freq/ div_factor) can also be used with more area
375	            cnt_sec = 0;
376	            freqA = cnt_A; // just the rounded KHz of
377	            freqB = cnt_B;
378	        } else {
379	            cnt_sec++;
380	        }
381	#endif // DBG_CHIPSCOPE
382	        if (!strm_cntEdge.empty()) {
383	            is_end = strm_calc_end.read();
384	            isNoEdge = false;
385	            edges_cur = strm_cntEdge.read();
386	#ifdef DBG_CHIPSCOPE
387	            if (isRaising(i_a, edges_cur)) {
388	                if (cnt_sec == 0)
389	                    cnt_A = 1;
390	                else
391	                    cnt_A++;
392	            }
393	            if (isRaising(i_b, edges_cur)) {
394	                if (cnt_sec == 0)
395	                    cnt_B = 1;
396	                else
397	                    cnt_B++;
398	            }
399	#endif // DBG_CHIPSCOPE
400	
401	            if (!isNormalEdges(edges_cur)) {
402	                ;
403	#ifdef DBG_CHIPSCOPE
404	                axi_qei_dir = (freqA + freqB) << 1; // just to keep the registers after synthesis
405	#endif
406	            } else { // valid edge(s)
407	                // interating counter
408	                if (isRaising(i_i, edges_cur))
409	                    counter = 0;
410	                else if (edges_cur.edges & 3) { // 4X mode : using any type of edges of A or B
411	                    if (dir)
412	                        counter = counter < ((int)(cpr << 2) - 1) ? counter + 1 : 0;
413	                    else
414	                        counter = counter == 0 ? ((int)(cpr << 2) - 1) : counter - 1;
415	                }
416	                // No A or B edges
417	                if (isNoABEdge(edges_cur)) continue;
418	
419	                if (isPreValid == true) {
420	                    // iterating dir and getting interval between two edges
421	                    processABedges(edges_pre, edges_cur, mode, dir, ii_cycles);
422	                    ap_uint<36> tmp_rpm = freq;
423	#pragma HLS BIND_OP variable = tmp_rpm op = mul impl = dsp
424	                    tmp_rpm *= 15; // 60 / 4
425	                    unsigned int div;
426	#pragma HLS BIND_OP variable = div op = mul impl = dsp
427	                    div = ii_cycles * cpr;
428	#ifndef __SYNTHESIS__
429	                    if (div == 0) printf("QEI_ERROR DIV=0\n");
430	                    assert(div != 0);
431	#endif
432	                    tmp_rpm = tmp_rpm / div;
433	
434	                    if (dir == Dirction_QEI::clockwise_p)
435	                        speed_rpm = tmp_rpm; // clockwise_p
436	                    else
437	                        speed_rpm = -tmp_rpm; // clockwise_n
438	                    ap_uint<32> tmp;
439	                    tmp.range(15, 0) = speed_rpm;
440	                    tmp.range(31, 16) = counter >> 2; // 4X mode : using any type of edges of A or B
441	                    axi_qei_rpm_theta_m.write((int)tmp);
442	                    // outputing
443	                    if (!out_speed_angle.full()) out_speed_angle.write((int)tmp);
444	                    if (!out_dirstr.full()) out_dirstr.write((T_bin)dir);
445	                    if (!out_errstr.full()) out_errstr.write((T_err)0);
446	                    axi_qei_dir.write(dir);
447	                    axi_qei_err.write(0);
448	                }
449	                isPreValid = true;
450	#ifndef __SYNTHESIS__
451	                edges_pre2.clone(edges_pre); // for printing
452	#endif
453	                edges_pre.clone(edges_cur);
454	            } // Normal edge(s)
455	            cnt_noEdge = 0;
456	        } else { // no edge
457	
458	#ifdef DBG_CHIPSCOPE
459	            if (cnt_sec == 0) {
460	                cnt_A = 0;
461	                cnt_B = 0;
462	            }
463	#endif // DBG_CHIPSCOPE
464	
465	            isNoEdge = true;
466	            if (cnt_noEdge == timeOut_noEdge - 1) {
467	                // debug tobe refine
468	                axi_qei_dir.write(counter >> 2); /// 4X mode : using any type of edges of A or B
469	                ap_uint<32> tmp_err;
470	                tmp_err.range(3, 0) = (ap_uint<4>)3;
471	                tmp_err.range(31, 4) = (ap_uint<28>)cnt_noEdge;
472	
473	                axi_qei_err.write(tmp_err);
474	                // reseting
475	                counter = 0;
476	                cnt_noEdge = 0;
477	                // outputing
478	                if (!out_speed_angle.full()) out_speed_angle.write(0);
479	                if (!out_dirstr.full()) out_dirstr.write((T_bin)dir);
480	                if (!out_errstr.full()) out_errstr.write((T_err)3);
481	
482	            } else
483	                cnt_noEdge++;
484	        } // no edge
485	//#define _DBG_QEI_WATCH_
486	#ifndef __SYNTHESIS__
487	
488	#ifdef _DBG_QEI_WATCH_
489	        int mode_noedge = timeOut_noEdge / 20;
490	        if (k == 0)
491	            printf(
492	                "DBG_QEI_WATCH:\t k\t noEdge\t PreValid\t pre.edges\t pre.types\t pre.time\t cur.edges\t cur.types\t "
493	                "cur.time\t counter\t speed_rpm\tii_cycles\tdir\terr \t preA\tcurA\tpreB\tcurB\tpreI\tcurI\n");
494	#ifdef DBG_CHIPSCOPE
495	        else if ((k != 1) && (cnt_noEdge % mode_noedge == 0 || isNoEdge == false || (cnt_sec == 0))) {
496	#else
497	        else if ((k != 1) && (cnt_noEdge % mode_noedge == 0 || isNoEdge == false)) {
498	#endif
499	            printf(
500	                "DBG_QEI_WATCH:\t %d\t %d\t %d\t%x\t %x\t %d\t %x\t %x\t %d\t %d\t %d\t%d\t%d\t%d  \t %d\t %d\t "
501	                "%d\t%d\t%d\t%d",
502	                k, cnt_noEdge, isPreValid, edges_pre2.edges, edges_pre2.types, edges_pre2.timeStep, edges_cur.edges,
503	                edges_cur.types, edges_cur.timeStep, counter, speed_rpm, ii_cycles, dir, axi_qei_err,
504	                edges_pre2.edges & 1, edges_cur.edges & 1, (edges_pre2.edges >> 1) & 1, (edges_cur.edges >> 1) & 1,
505	                (edges_pre2.edges >> 2) & 1, (edges_cur.edges >> 2) & 1);
506	#ifdef DBG_CHIPSCOPE
507	            printf("\t %d\t %d\t %d \t%d \t%d", cnt_sec, freqA, freqB, cnt_A, cnt_B);
508	#endif //#ifdef DBG_CHIPSCOPE
509	            printf("\n");
510	        }
511	#endif //_DBG_QEI_WATCH_
512	#endif //__SYNTHESIS__
513	
514	#ifndef __SYNTHESIS__
515	        k++;
516	#endif
517	    }
518	}
519	} // details
520	
521	/**
522	 * @brief Quadrature Encoder Interface(QEI) control demo top interface and paramters list
523	 * @tparam T_bin The data type for ABI's signals
524	 * @tparam T_err The data type for qei's error status
525	 * @param strm_qei_A The input stream for A signals
526	 * @param strm_qei_B The input stream for B signals
527	 * @param strm_qei_I The input stream for I signals
528	 * @param strm_qei_RPM_THETA_m The output stream for rpm and theta_m
529	 * @param strm_qei_dir The output stream for direction value
530	 * @param strm_qei_err The output stream for error status value
531	 * @param qei_args_cpr Read for user setting or written back by kernel
532	 * @param qei_args_ctrl The lowest bit of this value indicates the encoding mode
533	 * @param qei_stts_RPM_THETA_m Rpm and theta_m written back by kernel on axi_lite port
534	 * @param qei_stts_dir Dir written back by kernel on axi_lite port
535	 * @param qei_stts_err Err written back by kernel on axi_lite port
536	 * @param qei_args_cnt_trip input of trip count
537	 */
538	template <class T_bin, class T_err>
539	void hls_qei_axi(hls::stream<T_bin>& strm_qei_A,
540	                 hls::stream<T_bin>& strm_qei_B,
541	                 hls::stream<T_bin>& strm_qei_I,
542	                 hls::stream<ap_uint<32> >& strm_qei_RPM_THETA_m,
543	                 hls::stream<T_bin>& strm_qei_dir,
544	                 hls::stream<T_err>& strm_qei_err,
545	                 volatile int& qei_args_cpr,
546	                 volatile int& qei_args_ctrl,
547	                 hls::ap_none<int>& qei_stts_RPM_THETA_m,
548	                 hls::ap_none<int>& qei_stts_dir,
549	                 hls::ap_none<int>& qei_stts_err,
550	                 volatile long& qei_args_cnt_trip) {
551	#pragma HLS DATAFLOW
552	
553	    hls::stream<T_bin> strm_qei_A_out("strm_qei_A_out");
554	#pragma HLS STREAM depth = 16 variable = strm_qei_A_out
555	
556	    hls::stream<T_bin> strm_qei_B_out("strm_qei_B_out");
557	#pragma HLS STREAM depth = 16 variable = strm_qei_B_out
558	
559	    hls::stream<T_bin> strm_qei_I_out("strm_qei_I_out");
560	#pragma HLS STREAM depth = 16 variable = strm_qei_I_out
561	
562	    hls::stream<T_bin> strm_gen_quit_end("strm_gen_quit_end");
563	#pragma HLS STREAM depth = 16 variable = strm_gen_quit_end
564	
565	    hls::stream<ap_uint<4> > strm_qei_finalABI("strm_qei_finalABI");
566	#pragma HLS STREAM depth = 16 variable = strm_qei_finalABI
567	
568	    hls::stream<details::QEI_EdgeInfo> strm_cntEdge("strm_cntEdge");
569	#pragma HLS STREAM depth = 16 variable = strm_cntEdge
570	
571	    hls::stream<T_bin> strm_calc_end("strm_calc_end");
572	#pragma HLS STREAM depth = 16 variable = strm_calc_end
573	
574	    details::filterIn<T_bin>(strm_qei_A, strm_qei_B, strm_qei_I, qei_args_cnt_trip, strm_qei_finalABI);
575	    details::catchingEdge<T_bin>(strm_qei_finalABI, strm_cntEdge, strm_calc_end);
576	    details::calcCounter<T_bin, T_err>(strm_cntEdge, strm_calc_end, strm_qei_RPM_THETA_m, strm_qei_dir, strm_qei_err,
577	                                       qei_args_cpr, qei_args_ctrl, qei_stts_RPM_THETA_m, qei_stts_dir, qei_stts_err);
578	}
579	} // xf
580	} // motorcontrol
581	
582	#endif // _QEI_HPP_
