28	#ifndef _SVPWM_FP32_HPP_
29	#define _SVPWM_FP32_HPP_
30	
31	#include <cmath>
32	
33	namespace xf {
34	namespace motorcontrol {
35	namespace hls {
36	
37	//--------------------------------------------------------------------------
38	// SVPWM FP32
39	// Voff = (Vmin + Vmax) / 2
40	// Va_saddle = Va - Voff
41	// Vb_saddle = Vb - Voff
42	// Vc_saddle = Vc - Voff
43	// duty_ratio = (V_saddle + dc_link) / (2 * dc_link)
44	//--------------------------------------------------------------------------
45	
46	struct SVPWMOutput_fp32 {
47	    float duty_a;
48	    float duty_b;
49	    float duty_c;
50	    float voff;
51	    int sector;
52	    float va_saddle;
53	    float vb_saddle;
54	    float vc_saddle;
55	
56	    SVPWMOutput_fp32()
57	        : duty_a(0), duty_b(0), duty_c(0), voff(0), sector(0), va_saddle(0), vb_saddle(0), vc_saddle(0) {}
58	};
59	
60	inline float get_voff_fp32(float va, float vb, float vc) {
61	#pragma HLS INLINE
62	    float vmin = va;
63	    if (vb < vmin) vmin = vb;
64	    if (vc < vmin) vmin = vc;
65	    float vmax = va;
66	    if (vb > vmax) vmax = vb;
67	    if (vc > vmax) vmax = vc;
68	    float voff = (vmin + vmax) / 2.0f;
69	    return voff;
70	}
71	
72	inline float get_duty_ratio_fp32(float v_saddle, float dc_link) {
73	#pragma HLS INLINE
74	    float max_val = dc_link;
75	    float min_val = -dc_link;
76	    float v_clamped = v_saddle;
77	    if (v_clamped > max_val) v_clamped = max_val;
78	    if (v_clamped < min_val) v_clamped = min_val;
79	    float vp_saddle = v_clamped + max_val;
80	    float ratio = (vp_saddle / 2.0f) / max_val;
81	    if (ratio >= 1.0f) ratio = 0.99999f;
82	    if (ratio < 0.0f) ratio = 0.0f;
83	    return ratio;
84	}
85	
86	inline int determine_sector_fp32(float valpha, float vbeta) {
87	#pragma HLS INLINE
88	    const float PI = 3.14159265359f;
89	    float angle = std::atan2(vbeta, valpha);
90	    if (angle < 0.0f) angle += 2.0f * PI;
91	    int sector = static_cast<int>(angle / (PI / 3.0f)) + 1;
92	    if (sector > 6) sector = 6;
93	    if (sector < 1) sector = 1;
94	    return sector;
95	}
96	
97	/**
98	 * brief SVPWM duty cycle calculation in the form of an inline HLS function
99	 * param output     Output structure with duty cycles
100	 * param va_cmd     Phase A voltage command
101	 * param vb_cmd     Phase B voltage command
102	 * param vc_cmd     Phase C voltage command
103	 * param dc_link    DC link voltage
104	 */
105	inline void SVPWM_fp32(SVPWMOutput_fp32& output, float va_cmd, float vb_cmd, float vc_cmd, float dc_link) {
106	#pragma HLS INLINE
107	#pragma HLS PIPELINE II = 1
108	    float voff = get_voff_fp32(va_cmd, vb_cmd, vc_cmd);
109	    float va_saddle = va_cmd - voff;
110	    float vb_saddle = vb_cmd - voff;
111	    float vc_saddle = vc_cmd - voff;
112	    float duty_a = get_duty_ratio_fp32(va_saddle, dc_link);
113	    float duty_b = get_duty_ratio_fp32(vb_saddle, dc_link);
114	    float duty_c = get_duty_ratio_fp32(vc_saddle, dc_link);
115	    const float SQRT3_INV = 0.57735026919f;
116	    float valpha = va_cmd;
117	    float vbeta = SQRT3_INV * (vb_cmd - vc_cmd);
118	    int sector = determine_sector_fp32(valpha, vbeta);
119	    output.duty_a = duty_a;
120	    output.duty_b = duty_b;
121	    output.duty_c = duty_c;
122	    output.voff = voff;
123	    output.sector = sector;
124	    output.va_saddle = va_saddle;
125	    output.vb_saddle = vb_saddle;
126	    output.vc_saddle = vc_saddle;
127	}
